import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{o as r,c as t,f as p,b as e,d as h,e as d}from"./app-584b6577.js";const i={},o=e("h1",{id:"开心的生活总是那么短暂",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#开心的生活总是那么短暂","aria-hidden":"true"},"#"),h(" 开心的生活总是那么短暂")],-1),s=d('<h2 id="过去几年的在七牛的工作体验" tabindex="-1"><a class="header-anchor" href="#过去几年的在七牛的工作体验" aria-hidden="true">#</a> 过去几年的在七牛的工作体验</h2><h3 id="工作氛围" tabindex="-1"><a class="header-anchor" href="#工作氛围" aria-hidden="true">#</a> 工作氛围</h3><p>我的七牛工作经历大概从 2023 年 3 月到 2026 年 5 月,总的来说七牛的工作状态还是很好的,工作压力没那么大,早 10 晚 8 的生活</p><p>从工作中学习到互联网基础架构 CDN 的整体工作方式,也从七牛的 Miku 直播 CDN 产品从 0 到 1 参与并搭建起来.对业务/大数据处理流程有了清晰的认识.</p><p>整体来说七牛是一段相当不错的体验.</p><h3 id="这几天去哪玩了" tabindex="-1"><a class="header-anchor" href="#这几天去哪玩了" aria-hidden="true">#</a> 这几天去哪玩了</h3><p>5 月 22 日提了离职后,就一直在忙碌着,5 月 26 日去北京找梦梦.27,28 日和她在北京附近玩了一天,29 号去七牛的北京办公室开始出差交接.</p><p>29 号晚上去天津财经找 zzx 玩,30号玩了一整天,印象里最深刻的就是绕着海河走了有好几公里.期间有一搭没一搭聊着狗屁未来,似乎又回到了百无聊赖的大学生活,7 月 1 号大早上去继续回北京上班,当天晚上去顺义亲戚家睡了一晚上.</p><p>7 月 4 日周四 23 年和我一起在七牛实习的胡立伟从温州来北京参加 ETH 的黑客松开发者 又一起约了顿饭(笑死,5 月 1 号前我们才约了饭聊了聊币圈的理财产品怎么搞),7 月 5 日又去北京办公室 晚上 11 点和梦梦去就坐上了去威海的火车.</p><p>7 月 6 日我们到了威海,接着到9 号我们一直都在威海玩.威海的风景不错,租一辆四轮的电动 mini 车只需要 60 一天算上电费也就 70 左右.但是第一天我们就被坑了 200 元,原因是不太熟悉交了保险,另外就在酒店附近租的车比较贵...也算是一种体验.</p><p>从 6 号到 9 号连着三四天把威海该逛的景点逛了遍,玩得很开心.</p><p>9 号我们就从威海离开了,当天回上海.11 号我和瑛琪又去爬黄山玩,黄山脚下的民宿都很坑,好在我们去的比较不错,也没有被坑到.</p><p>爬黄山用了 5 个小时,比爬武功山要久一些,但是我们还是很开心的.碰到了野生的松鼠猴子,当天下午去了千岛湖,住了一天酒店第二天就回来了(悲,本来想爬完黄山就去再爬一次武功山,有点担心猝死就没去哈哈</p><p>接着 15-18 日我就正常在七牛上班,把自己的事情都认真交接了出去.</p><p>20 号 18 点临时去苏州玩,当天晚上 11 点回上海.</p><p>21 号晚上出去吃了个海底捞</p><p>22 号迎接我的第一次 lastday.</p><h3 id="后面的计划" tabindex="-1"><a class="header-anchor" href="#后面的计划" aria-hidden="true">#</a> 后面的计划</h3><p>22 号晚去深圳, 23 号看一天租房子 24 号去上班~</p>',19);function c(n,l){return r(),t("div",null,[o,p(" more "),s])}const m=a(i,[["render",c],["__file","happy-life-is-always-too-short.html.vue"]]);export{m as default};
